"""Policy syntax: lazy tokenizer, recursive-descent parser, declared bounds.

A policy string is zero or more ``PREDICATE ACTION;`` rules.  Only the five
declared whitespace characters separate tokens; vertical tab and every other
Unicode whitespace character is a syntax error.  Parsing never depends on the
service registry, so a syntactically valid string can be counted for the
whole-request atom/path totals even when it names an unknown service.
"""

import re

__all__ = ['PolicyError', 'parse_policy', 'iter_atoms', 'atom_stats']

DENY = 4294967295

MAX_DEPTH = 16
MAX_PATH = 16
MAX_COMPLEX_RULES = 8
MAX_COMPLEX_ATOMS = 32
MAX_NONMATCH_DISTINCT = 4
MAX_NONMATCH_PATH = 4
MAX_ATOMS = 32768
MAX_PATHSYM = 65536

ATOM_OPS = frozenset(('match', 'startswith', 'endswith', 'contains'))
PUNCT = '();,'
_ALLOWED_WS = ' \t\f\r\n'

# One pass of the tokenizer yields names, punctuation or a forbidden character.
# Whitespace runs produce no group and are simply skipped.
_TOKEN = re.compile(
    '[ \t\f\r\n]+'
    '|([A-Za-z][A-Za-z0-9]{0,23})'
    '|([();,])'
    '|([\\s\\S])'
)


class PolicyError(ValueError):
    """Syntactically invalid policy, or a declared policy bound violation."""


def _tokens(text):
    for matched in _TOKEN.finditer(text):
        name = matched.group(1)
        if name is not None:
            yield name
            continue
        punct = matched.group(2)
        if punct is not None:
            yield punct
            continue
        # Vertical tab and every other Unicode whitespace/code point that is
        # not a declared token character rejects the stage.
        raise PolicyError('forbidden character')


class _Reader(object):
    """One token of lookahead over a lazy token stream."""

    __slots__ = ('_it', 'ahead', 'live')

    def __init__(self, tokens):
        self._it = tokens
        self.ahead = next(tokens, None)
        self.live = self.ahead is not None

    def peek(self):
        return self.ahead

    def take(self):
        token = self.ahead
        if token is None:
            raise PolicyError('unexpected end of policy')
        self.ahead = next(self._it, None)
        self.live = self.ahead is not None
        return token


def _pred(reader, level):
    token = reader.peek()
    if token == '(':
        reader.take()
        left = _pred(reader, level + 1)
        op = reader.take()
        if op != 'and' and op != 'or':
            raise PolicyError('boolean operator')
        right = _pred(reader, level + 1)
        if reader.take() != ')':
            raise PolicyError('parenthesis')
        return ('b', op, left, right)
    if token == 'not':
        reader.take()
        if reader.take() != '(':
            raise PolicyError('parenthesis')
        inner = _pred(reader, level + 1)
        if reader.take() != ')':
            raise PolicyError('parenthesis')
        return ('n', inner)
    if token in ATOM_OPS:
        reader.take()
        if reader.take() != '(':
            raise PolicyError('parenthesis')
        path = []
        if reader.peek() != ')':
            while True:
                item = reader.take()
                if item is None or item in PUNCT:
                    raise PolicyError('path')
                path.append(item)
                if reader.peek() == ',':
                    reader.take()
                    continue
                break
        if reader.take() != ')':
            raise PolicyError('parenthesis')
        if len(path) > MAX_PATH:
            raise PolicyError('path length')
        if level + 1 > MAX_DEPTH:
            raise PolicyError('predicate depth')
        return ('atom', token, tuple(path))
    raise PolicyError('predicate')


def iter_atoms(tree):
    """Yield every ``(operator, path)`` leaf of a predicate tree."""
    stack = [tree]
    pop = stack.pop
    push = stack.append
    while stack:
        node = pop()
        kind = node[0]
        if kind == 'atom':
            yield node[1], node[2]
        elif kind == 'n':
            push(node[1])
        else:
            push(node[2])
            push(node[3])


def atom_stats(tree):
    """Return ``(atom occurrences, path-service occurrences, complex)``."""
    atoms = 0
    symbols = 0
    complex_rule = not (tree[0] == 'atom' and tree[1] == 'match')
    for _op, path in iter_atoms(tree):
        atoms += 1
        symbols += len(path)
    return atoms, symbols, complex_rule


def parse_policy(text):
    """Parse one policy string.

    Returns ``(rules, atom_occurrences, path_service_occurrences)`` where every
    rule is a ``(predicate_tree, allow_flag)`` pair, or raises ``PolicyError``.
    """
    reader = _Reader(_tokens(text))
    rules = []
    atoms = 0
    symbols = 0
    complex_rules = 0
    nonmatch = set()
    while reader.live:
        tree = _pred(reader, 0)
        action = reader.take()
        if action == 'allow':
            flag = True
        elif action == 'drop':
            flag = False
        else:
            raise PolicyError('action')
        if reader.take() != ';':
            raise PolicyError('rule terminator')
        count, pathlen, complex_rule = atom_stats(tree)
        if complex_rule:
            complex_rules += 1
            if count > MAX_COMPLEX_ATOMS:
                raise PolicyError('expression atom bound')
        else:
            for op, path in iter_atoms(tree):
                if op != 'match' and len(path) > MAX_NONMATCH_PATH:
                    raise PolicyError('non-match path length')
        if op_nonmatch(tree, nonmatch) > MAX_NONMATCH_DISTINCT:
            raise PolicyError('distinct non-match atom bound')
        atoms += count
        symbols += pathlen
        if atoms > MAX_ATOMS or symbols > MAX_PATHSYM:
            raise PolicyError('string atom bound')
        rules.append((tree, flag))
    if complex_rules > MAX_COMPLEX_RULES:
        raise PolicyError('complex rule bound')
    if len(nonmatch) > MAX_NONMATCH_DISTINCT:
        raise PolicyError('distinct non-match atom bound')
    return rules, atoms, symbols


def op_nonmatch(tree, seen):
    for op, path in iter_atoms(tree):
        if op != 'match':
            seen.add((op, path))
    return len(seen)
